import java.util.*;

class Solution {
  public int minImpossibleOR(int[] nums) {
    boolean[] present = new boolean[31];
    for (int value : nums)
      if (value > 0 && (value & (value - 1)) == 0) {
        present[Integer.numberOfTrailingZeros(value)] = true;
      }
    for (int bit = 0; bit < present.length; bit++) if (!present[bit]) return 1 << bit;
    return 1 << 30;
  }
}
